//  DR戦略 12 / 目的別データベース 12 / セキュリティ深掘り 14 /
//  ネットワーク深掘り 12 / コンピュート・高性能 10 /
//  アプリ統合・疎結合 8 / ストレージ深掘り 7 / 運用・IaC 5
//
// 【選択肢の鉄則（既存3バンクと同じ）】
//  1. 4択すべてAWSサービスを使った技術的に正しい方法
//  2. 手作業・現状維持・ゴミ選択肢を入れない
//  3. 正解と誤答の差は要件適合度・コスト・制約・運用負荷だけ
//  4. 誤答は自分の欠点を本文で自己申告しない（中立に書く・理由はelimへ）
//  5. ask末尾は本番形式「これらの要件を満たす、最も〇〇なソリューションはどれですか？」
//  6. 複数選択(2つ選ぶ)も混ぜる。混同ペアはconfusion、用語はtermsで補足
// index.htmlのBANKSにv4登録済み（D・本番ギャップ）。
// ============================================================
