  scenario:"ある企業が、オンプレで動くMongoDBベースのアプリをAWSへ移行したい。データはJSONドキュメント中心で、アプリは既存のMongoDBドライバ/APIを使い続けたい。要件は『MongoDB互換のままマネージドに運用し、サーバー管理・パッチ・バックアップ・スケールをAWSに任せたい』。",
