  explain:'Amazon DocumentDBはMongoDB互換のマネージドドキュメントデータベースで、既存のMongoDBドライバ/APIをほぼそのまま使え、運用(パッチ・バックアップ・スケール)をAWSに任せられる。MongoDBアプリの移行先の定番。',
  elim:'B=DynamoDBはキーバリュー/ドキュメントだがMongoDB APIではなくアプリの書き換えが要る。C=RDS PostgreSQLのJSONBでも格納はできるがMongoDB APIではない。D=Neptuneはグラフ用でドキュメントDBではない。「MongoDB互換のまま」が決め手＝DocumentDB。',
