  answer:0,
  keypoint:'キーワードは「IoTセンサーの秒単位の計測値」「時刻でインデックス」「時間範囲集計」「古いデータを自動で安価な層へ」。時系列専用DBを選ぶ。',
  explain:'Amazon Timestreamは時系列データ専用のマネージドDBで、大量の時刻付きデータの高速な取り込みと時間範囲クエリに最適化され、直近はメモリ層・古いデータは磁気層へ自動階層化できる。IoT/メトリクス用途の定番。',
  elim:'B=RDBに高頻度INSERTはスケールしにくく時系列クエリにも最適化されていない。C=Redshiftは大規模分析DWHで、継続的な時系列取り込み＋直近高速参照には過剰/不向き。D=DynamoDBでも保存はできるが時系列関数や自動階層化を持たず最適でない。時系列専用はTimestream。',
