  explain:'Amazon OpenSearch Serviceは全文検索・曖昧検索・ファセット集計に最適化された検索分析エンジンで、付属のダッシュボードでログをほぼリアルタイムに可視化できる。検索とログ分析の用途の定番。',
  elim:'B=RDBのLIKEは全文検索に最適化されておらず大規模・曖昧検索で遅い。C=DynamoDBのScanは全件走査で全文検索用途に不向き。D=Athenaはアドホックなバッチ分析向きで、低レイテンシの全文検索やリアルタイムダッシュボードには向かない。検索＋可視化はOpenSearch。',
