  explain:'Amazon DynamoDBはキーバリュー/ドキュメントのサーバーレスNoSQLで、オンデマンドキャパシティで予測不能なトラフィックにほぼ無限にスケールしつつ一桁ミリ秒の低レイテンシを保つ。キー中心アクセス・JOIN不要の要件に最適。',
  elim:'B=RDBの垂直スケールには上限があり、予測不能な急増・無限スケールには追従しにくい。C=Redshiftは分析DWHでトランザクション的なキーアクセスではない。D=EC2自前MySQL＋自作シャーディングは運用負荷が極めて高い。キー中心＋無限スケール＋サーバーレスはDynamoDB。',
