  explain:'Amazon AuroraはMySQL/PostgreSQL互換のクラウド最適化マネージドRDBで、ストレージは自動拡張、複数AZにまたがる高可用構成で自動フェイルオーバーし、商用DB級の性能を提供する。リレーショナルで高性能・高可用をマネージドで欲しい時の定番。',
