  explain:'AWS Client VPNはマネージドなリモートアクセスVPNで、個々の従業員のデバイス(OpenVPNベースのクライアント)から認証してVPC内のプライベートリソースへ安全に接続できる。リモートワーカーの個人デバイス接続に最適。',
