  scenario:"あるサービスが、非HTTPのTCPトラフィックを超低遅延・超高スループットで負荷分散したい。要件は『L4(TCP/UDP)で動作し、極めて高い性能と低遅延を提供する』『クライアントへ提示する固定IP(静的IP)が必要』。HTTPのパスベースルーティング等は不要。",
