  keypoint:'キーワードは「エッジで超軽量・超低レイテンシ」「URL書き換え/ヘッダー操作/簡単なリダイレクト/トークン検証」「非常に高頻度・低コスト」「重い処理や外部アクセス不要」。超軽量エッジ処理はCloudFront Functions。',
  explain:'CloudFront Functionsは、CloudFrontのエッジで実行される超軽量・超低レイテンシな関数で、ヘッダー操作・URL書き換え・簡単なリダイレクト・トークン検証などを高頻度・低コストで処理できる。重い処理や外部ネットワークアクセスが不要な軽量処理に最適。',
  elim:'B=Lambda@Edgeはより重い処理や外部アクセスができるが、超軽量・超高頻度・最低コストの要件にはCloudFront Functionsが適する(今回は重い処理不要)。C=オリジンEC2で全処理はエッジの低レイテンシを活かせない。D=API Gateway+Lambdaの別構築は過剰。軽量エッジ処理はCloudFront Functions。',
