  explain:'Amazon MQはApache ActiveMQ/RabbitMQのマネージドサービスで、JMS・AMQP・MQTT・STOMP等の業界標準プロトコルをサポートする。既存のメッセージングコードを書き換えずにオンプレのブローカーから移行できる(リフト&シフト)。',
