    "Amazon EventBridgeでイベントをルールに基づき各サービスへルーティングし、発生源と処理を疎結合にする。",
    "各サービスが次のサービスのAPIを同期的に直接呼び出すチェーンを組み、在庫引当→決済→出荷指示を順番に連携させる。",
    "AWS Step Functionsで注文処理の多段ワークフローを、リトライ・分岐を含めて状態管理しながらオーケストレーションする。"
