  explain:'Storage GatewayのTape Gatewayは仮想テープライブラリ(VTL)として動作し、既存のテープバックアップソフトから見ると物理テープライブラリと同じインターフェイスで使え、バックアップを仮想テープとしてS3/S3 Glacierに保管できる。物理テープの置き換えに最適。',
