  explain:'Storage GatewayのFile Gatewayは、オンプレからNFS/SMBでアクセスできるファイル共有を提供しつつ、実体をS3オブジェクトとして保存する。よくアクセスするファイルはローカルにキャッシュして低遅延にできる。オンプレのファイル共有をS3に橋渡しする定番。',
