  keypoint:'2つ選ぶ問題。「基準からの逸脱を継続評価→Config Rules」「逸脱を自動修復→Configの修復アクション(SSM Automation)」。AとBが検出と自動修復を担う。Cは手作業で抜け漏れ、Dはログ分析で構成評価にならない。',
  explain:'A＝AWS Configのルールはリソース構成が基準(暗号化必須・公開禁止等)から逸脱していないか継続的に評価する。B＝Configの修復アクションにSystems Manager Automationドキュメントを関連付ければ、逸脱検出時に定型修復(暗号化有効化・公開SG修正等)を自動実行できる。検出＋自動修復の組み合わせ。',
